import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type JobCounter struct {
	count atomic.Int64
}

func (jc *JobCounter) Increment() {
	jc.count.Add(1)
}

func (jc *JobCounter) Value() int {
	return int(jc.count.Load())
}

