for i := 0; i < numWorkers; i++ {
	wg.Add(1)
	go func(id int) {
		defer wg.Done()
		for job := range jobs {
			// Simulate some work
			time.Sleep(time.Millisecond)

			processedCount.Increment()

			results <- Result{JobID: job.ID, Val: job.ID * 2}
		}
	}(i)
}

// Send jobs
go func() {
	for i := 0; i < numJobs; i++ {
		jobs <- Job{ID: i}
	}
	close(jobs)
}()

// Goroutine to consume results concurrently
resultsWg.Add(1)
go func() {
	defer resultsWg.Done()
	for range results {
		// Just drain
	}
}()

